static const double TRUE_MEDIAN = 49.94282953125205;

double frugal_streaming_median(const std::vector<double>& stream, const std::vector<double>& coins, double step=1.0) {
    double q = 0.5;
    double m = 0.0;
    for (size_t i = 0; i < stream.size(); ++i) {
        double x = stream[i], r = coins[i];
        if (x > m && r > 1.0 - q) m += step;
        else if (x < m && r > q) m -= step;
    }
    return m;
}

int main() {
    double est = frugal_streaming_median(STREAM, COINS, 1.0);
    double err = std::abs(est - TRUE_MEDIAN);
    std::cout << "Frugal-1 median: est=" << est << ", true=" << TRUE_MEDIAN << ", err=" << err << std::endl;
    assert(err < 3.0);
    std::cout << "Frugal median PASS" << std::endl;
    return 0;
}
